const companies=[{t:'NVDA',n:'NVIDIA Corporation',s:'Technology',p:124.92,c:2.34,cap:'3.06T',pe:58.4,rev:60.9,margin:48.9,growth:126,brief:'Revenue momentum is strong, supported by demand for accelerated computing. Compare growth against valuation and customer concentration.'},{t:'AAPL',n:'Apple Inc.',s:'Technology',p:227.55,c:0.82,cap:'3.46T',pe:34.7,rev:383.3,margin:25.3,growth:2.1,brief:'A large recurring services business supports profitability. Watch hardware demand, services mix, and the valuation multiple.'},{t:'MSFT',n:'Microsoft Corporation',s:'Technology',p:428.76,c:1.26,cap:'3.19T',pe:36.2,rev:245.1,margin:35.9,growth:15.7,brief:'Cloud and enterprise software support diversified growth. Evaluate capital spending alongside cash flow and operating margins.'},{t:'GOOGL',n:'Alphabet Inc.',s:'Technology',p:165.85,c:-0.48,cap:'2.03T',pe:23.6,rev:307.4,margin:24,growth:8.7,brief:'Advertising provides a substantial earnings base. Monitor cloud profitability, search competition, and reinvestment.'},{t:'AMZN',n:'Amazon.com Inc.',s:'Consumer',p:186.51,c:1.73,cap:'1.96T',pe:44.1,rev:574.8,margin:5.3,growth:11.8,brief:'Cloud and retail offer distinct profit drivers. Track segment margins, fulfillment efficiency, and free cash flow.'},{t:'META',n:'Meta Platforms Inc.',s:'Technology',p:563.33,c:1.15,cap:'1.42T',pe:28.7,rev:134.9,margin:28.9,growth:15.7,brief:'Advertising growth and operating discipline support earnings. Assess infrastructure spending and long-term product investment.'},{t:'TSLA',n:'Tesla Inc.',s:'Consumer',p:238.77,c:-2.16,cap:'763.4B',pe:62.5,rev:96.8,margin:15.5,growth:18.8,brief:'Vehicle demand and pricing shape near-term results. Monitor margins, competitive pressure, and spending on new businesses.'}];
let watch;try{watch=JSON.parse(localStorage.getItem('fiscal-watch'))||['NVDA','AAPL','MSFT','GOOGL','AMZN']}catch{watch=['NVDA','AAPL','MSFT','GOOGL','AMZN']}let selected=companies[0],view='overview',tab='price',range='1Y',sortKey='cap',sortAsc=false;const $=id=>document.getElementById(id);const money=v=>'$'+v.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});const pct=v=>(v>=0?'+':'')+v.toFixed(2)+'%';
function toast(s){$('toast').textContent=s;$('toast').style.opacity=1;setTimeout(()=>$('toast').style.opacity=0,2300)}function save(){localStorage.setItem('fiscal-watch',JSON.stringify(watch));$('count').textContent=watch.length;$('star').textContent=watch.includes(selected.t)?'★':'☆'}
function spark(c,i=0){let pts=Array.from({length:24},(_,j)=>`${j*4},${20-j*.5-Math.sin(j*1.7+i)*4}`).join(' ');return `<svg class="spark" viewBox="0 0 95 25"><polyline points="${pts}" fill="none" stroke="${c>=0?'#22a582':'#df7d89'}" stroke-width="1.5"/></svg>`}
$('markets').innerHTML=[['S&P 500','5,751.07',0.97],['NASDAQ','18,137.85',1.45],['DOW JONES','42,512.00',0.62],['VIX','20.46',-2.38]].map((m,i)=>`<div class="market"><span class="label">${m[0]}</span><strong>${m[1]}</strong><small class="${m[2]>=0?'positive':'negative'}">${pct(m[2])} <span style="color:var(--muted)"> illustrative</span></small>${spark(m[2],i)}</div>`).join('');
function chart(){let period=['1M','3M','6M','1Y','5Y'].indexOf(range)+1;let vals=Array.from({length:70},(_,i)=>120-i*1.05-Math.sin(i*.7+period)*9-Math.cos(i*2.1)*4+Math.sin(i*.12)*16);let pts=vals.map((v,i)=>`${i*8},${v}`).join(' ');let lines=[20,60,100,140,180].map((y,i)=>`<line x1="0" y1="${y}" x2="570" y2="${y}" stroke="var(--line)" stroke-dasharray="3 4"/><text x="580" y="${y+3}" font-size="9" fill="#9a9eaa">${tab==='price'?Math.round(selected.p*(1.2-i*.18)):Math.round(selected.rev*(1-i*.18))}</text>`).join('');$('chart').innerHTML=`<svg role="img" aria-label="Illustrative ${tab} chart for ${selected.n}, ${range}" viewBox="0 0 615 200" preserveAspectRatio="none"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#957ce9" stop-opacity=".18"/><stop offset="1" stop-color="#957ce9" stop-opacity="0"/></linearGradient></defs>${lines}<polygon points="0,190 ${pts} 552,190" fill="url(#fill)"/><polyline points="${pts}" fill="none" stroke="#9072e6" stroke-width="2.3"/><circle cx="552" cy="${vals[69]}" r="3" fill="#9072e6"/></svg>`;$('chartLabel').textContent=tab==='price'?'PRICE PERFORMANCE · '+range:tab.toUpperCase()+' · ILLUSTRATIVE TREND';}
function select(c){selected=c;$('companyName').textContent=c.n;$('ticker').textContent=c.t;$('logo').textContent=c.t[0];$('sector').textContent=c.s;$('price').textContent=money(c.p);$('change').textContent=pct(c.c);$('change').className=c.c>=0?'positive':'negative';$('metrics').innerHTML=[['Market cap','$'+c.cap],['P/E ratio',c.pe.toFixed(1)+'×'],['Revenue (TTM)','$'+c.rev+'B'],['Net profit margin',c.margin+'%'],['Revenue growth',c.growth+'%']].map(([k,v])=>`<div class="metric"><span>${k}</span><strong>${v}</strong></div>`).join('');$('insight').textContent=c.brief;save();chart()}
function rows(){let list=companies.filter(c=>(view==='screener'||watch.includes(c.t))&&($('filter').value==='all'||c.s===$('filter').value)&&(`${c.t} ${c.n}`.toLowerCase().includes($('search').value.toLowerCase())));return list.sort((a,b)=>{let av=a[sortKey],bv=b[sortKey];if(sortKey==='cap'){av=parseFloat(av)*(av.endsWith('T')?1000:1);bv=parseFloat(bv)*(bv.endsWith('T')?1000:1)}return(typeof av==='string'?av.localeCompare(bv):av-bv)*(sortAsc?1:-1)})}
function renderTable(){if(view==='financials'){$('tableTitle').textContent=selected.n+' · Financials';$('tableSubtitle').textContent='Illustrative annual income statement · USD billions';$('thead').innerHTML='<tr><th>Income statement</th><th>FY 2021</th><th>FY 2022</th><th>FY 2023</th><th>FY 2024</th><th>Growth</th></tr>';$('tbody').innerHTML=[['Revenue',1],['Gross profit',.62],['Operating income',.35],['Net income',selected.margin/100],['Free cash flow',.31]].map(([n,m])=>`<tr><td>${n}</td>${[.54,.64,.8,1].map(f=>`<td>${(selected.rev*m*f).toFixed(2)}</td>`).join('')}<td class="positive">+25.0%</td></tr>`).join('');$('resultCount').textContent='5 financial metrics';return}let list=rows();$('tableTitle').textContent=view==='screener'?'Discover companies':'Your watchlist';$('tableSubtitle').textContent=view==='screener'?'Filter, compare, and find your next research idea.':"The companies you're keeping an eye on.";$('thead').innerHTML='<tr>'+[['Company','n'],['Price','p'],['Change','c'],['Market cap','cap'],['P/E ratio','pe'],['Revenue growth','growth'],['Trend','trend']].map(([n,k])=>`<th data-sort="${k}">${n}${sortKey===k?(sortAsc?' ↑':' ↓'):''}</th>`).join('')+'</tr>';$('tbody').innerHTML=list.length?list.map((c,i)=>`<tr data-ticker="${c.t}"><td><div class="cell-company"><div class="mini-icon">${c.t[0]}</div><div><strong>${c.t}</strong><small>${c.n}</small></div></div></td><td>${money(c.p)}</td><td class="${c.c>=0?'positive':'negative'}">${pct(c.c)}</td><td>$${c.cap}</td><td>${c.pe}×</td><td class="positive">+${c.growth}%</td><td>${spark(c.c,i)}</td></tr>`).join(''):'<tr><td colspan="7" style="text-align:center">No companies found. Search another ticker or explore the screener.</td></tr>';$('resultCount').textContent=`Showing ${list.length} companies`;document.querySelectorAll('[data-ticker]').forEach(el=>el.onclick=()=>{select(companies.find(c=>c.t===el.dataset.ticker));window.scrollTo({top:0,behavior:'smooth'})});document.querySelectorAll('[data-sort]').forEach(el=>el.onclick=()=>{if(el.dataset.sort==='trend')return;sortAsc=sortKey===el.dataset.sort?!sortAsc:false;sortKey=el.dataset.sort;renderTable()})}
function setView(v){view=v;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));let title={overview:'Market overview',watchlist:'Your watchlist',screener:'Stock screener',financials:'Company financials'}[v];$('heading').textContent=title;$('crumb').textContent=title;$('markets').style.display=v==='financials'?'none':'grid';renderTable()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('selected',x===b));chart()});document.querySelectorAll('#ranges button').forEach(b=>b.onclick=()=>{range=b.textContent;document.querySelectorAll('#ranges button').forEach(x=>x.classList.toggle('selected',x===b));chart()});$('filter').onchange=renderTable;$('search').oninput=()=>{if(view!=='screener')setView('screener');renderTable();const matches=rows();if(matches.length===1)select(matches[0])};function toggle(){watch=watch.includes(selected.t)?watch.filter(t=>t!==selected.t):[...watch,selected.t];save();renderTable();toast(watch.includes(selected.t)?selected.t+' added to watchlist':selected.t+' removed from watchlist')}$('star').onclick=toggle;$('add').onclick=()=>{if(watch.includes(selected.t)){setView('screener');$('search').focus();toast('Select a company, then use its star to save it.')}else toggle()};$('explore').onclick=()=>{setView('screener');$('search').focus()};$('theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('fiscal-dark',document.body.classList.contains('dark'))};if(localStorage.getItem('fiscal-dark')==='true')document.body.classList.add('dark');document.addEventListener('keydown',e=>{if(e.key==='/'&&document.activeElement.tagName!=='INPUT'){e.preventDefault();$('search').focus()}});$('export').onclick=()=>{const table=document.querySelector('table');const csv=Array.from(table.rows).map(r=>Array.from(r.cells).map(c=>'"'+c.innerText.replaceAll('"','""').replaceAll('\n',' ')+'"').join(',')).join('\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));let a=document.createElement('a');a.href=url;a.download='akhil-ai-'+view+'.csv';a.click();URL.revokeObjectURL(url);toast('CSV exported')};select(selected);renderTable();
